1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: Damage[];
19	};
20	
21	/**
22	 * One type covers both ops, so items/policy/incident are all optional. A
23	 * discriminated union on `op` would express this better, but the spec's
24	 * scenarios are plain object literals whose `op` widens to `string` and so
25	 * would no longer typecheck against literal `"quote"` / `"claim"` variants.
26	 * Revisit if a scenario parser ever narrows `op` on the way in.
27	 */
28	export type Step = {
29	  op: string;
30	  items?: Item[];
31	  policy?: number;
32	  incident?: Incident;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	export type ScenarioResult = {
44	  results: (QuoteResult | ClaimResult)[];
45	};
46	
47	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	};
55	/**
56	 * Deliberately NOT derived from the base premiums, though every entry today
57	 * happens to be 10x its counterpart. The MHPCO publishes two independent
58	 * price lists ("Sword: 1000 G insurance value, 100 G base premium"), and the
59	 * rules already pull them apart: the 3-alike building block cuts the base
60	 * premium to 60 G while the insurance value stays 250 G per component. Making
61	 * one a function of the other would encode a coincidence as a rule.
62	 *
63	 * A test now guards this — "caps a policy covering a sword and 3 runes at
64	 * 3500 G". Deriving these values from the base premiums, or routing both
65	 * through a shared summing helper, makes the block rule reach the insurance
66	 * sum and yields a cap of 2120 instead of 3500.
67	 */
68	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	const DEDUCTIBLE = 100;
77	const CAP_MULTIPLE = 2;
78	const HIGH_ENCHANTMENT_PAYOUT_THRESHOLD = 8;
79	const HIGH_ENCHANTMENT_PAYOUT_PERCENT = 50;
80	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
81	const CURSE_SURCHARGE_PERCENT = 50;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
84	const LOYALTY_THRESHOLD_YEARS = 2;
85	const LOYALTY_DISCOUNT_PERCENT = 20;
86	const FOLLOWUP_DISCOUNT_PERCENT = 15;
87	const PROCESSING_FEE = 5;
88	
89	/**
90	 * Not a tunable constant — this is what "per cent" means. It is named only
91	 * because the divisor reads as a bare literal otherwise; nothing should ever
92	 * change it.
93	 */
94	const PERCENT_DIVISOR = 100;
95	
96	const percentOf = (amount: number, percent: number): number =>
97	  (amount * percent) / PERCENT_DIVISOR;
98	
99	/**
100	 * The MHPCO insures only what is on its price list. Looking a type up through
101	 * here rather than indexing a table directly means an unknown type cannot slip
102	 * through as `undefined` and surface later as a NaN premium.
103	 */
104	const priceOf = (
105	  priceList: Record<string, number>,
106	  itemType: string,
107	): number => {
108	  const price = priceList[itemType];
109	  if (price === undefined) {
110	    throw new Error(`unknown item type: ${itemType}`);
111	  }
112	  return price;
113	};
114	
115	/**
116	 * Premiums round UP — the MHPCO's favour on money coming IN. Payouts will need
117	 * the opposite direction, so this deliberately names the premium case only
118	 * rather than a general "in the MHPCO's favour" rounding.
119	 */
120	const roundPremiumUp = (premium: number): number => Math.ceil(premium);
121	
122	const BLOCK_SIZE = 3;
123	const BLOCK_BASE_PREMIUM = 60;
124	
125	/**
126	 * Tallies how often each key occurs. Shared by the two things the MHPCO counts
127	 * by type — the items ON a policy and the damages claimed AGAINST it — which
128	 * are different domain concepts over different shapes, but genuinely the same
129	 * counting. The key is supplied by the caller precisely so neither concept has
130	 * to borrow the other's field name.
131	 */
132	const countByKey = <T>(values: T[], keyOf: (value: T) => string): Map<string, number> =>
133	  values.reduce(
134	    (counts, value) =>
135	      counts.set(keyOf(value), (counts.get(keyOf(value)) ?? 0) + 1),
136	    new Map<string, number>(),
137	  );
138	
139	/** Counts of items of the same type — "alike" in the MHPCO's terms. */
140	const countAlikeItems = (items: Item[]): Map<string, number> =>
141	  countByKey(items, (item) => item.type);
142	
143	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
144	
145	const basePremiumForAlikeItems = (type: string, count: number): number =>
146	  formsBuildingBlock(count)
147	    ? BLOCK_BASE_PREMIUM
148	    : count * priceOf(BASE_PREMIUM_BY_ITEM_TYPE, type);
149	
150	const policyBasePremium = (items: Item[]): number =>
151	  [...countAlikeItems(items)].reduce(
152	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
153	    0,
154	  );
155	
156	const itemBasePremium = (item: Item): number =>
157	  priceOf(BASE_PREMIUM_BY_ITEM_TYPE, item.type);
158	
159	/**
160	 * An absent `enchantment` reads as 0 — a plain rune is not enchanted at all.
161	 * The threshold is a parameter because the MHPCO sets two different bars: 5
162	 * for the premium surcharge, 8 for the payout clause.
163	 */
164	const enchantmentAtLeast = (item: Item, threshold: number): boolean =>
165	  (item.enchantment ?? 0) >= threshold;
166	
167	const isHighlyEnchanted = (item: Item): boolean =>
168	  enchantmentAtLeast(item, HIGH_ENCHANTMENT_THRESHOLD);
169	
170	/** Item-specific surcharges stack additively. */
171	const itemSurchargePercent = (item: Item): number =>
172	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
173	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
174	
175	/**
176	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
177	 * premium — unlike policy-wide modifiers, which apply to the policy base.
178	 */
179	const totalItemSurcharges = (items: Item[]): number =>
180	  items.reduce(
181	    (total, item) =>
182	      total + percentOf(itemBasePremium(item), itemSurchargePercent(item)),
183	    0,
184	  );
185	
186	const isLongStanding = (customer: Customer): boolean =>
187	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
188	
189	/**
190	 * The net of all policy-wide percentages. Policy-wide modifiers are
191	 * percentages of the POLICY base premium — unlike item-specific modifiers,
192	 * which apply to the affected item's own base. The net is negative when the
193	 * discounts outweigh the surcharges: a long-standing customer nets -10 %.
194	 */
195	const netPolicyAdjustmentPercent = (
196	  customer: Customer,
197	  precedingSteps: number,
198	): number =>
199	  FIRST_INSURANCE_SURCHARGE_PERCENT -
200	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0) -
201	  // The follow-up discount is owed on every quote after the customer's FIRST
202	  // QUOTE, but what we have here is a count of preceding STEPS. The two
203	  // coincide only because every step exercised so far is a quote; once claim
204	  // steps arrive, [quote, claim, quote] will wrongly discount the third step
205	  // as a second follow-up. No test forces the distinction yet.
206	  (precedingSteps > 0 ? FOLLOWUP_DISCOUNT_PERCENT : 0);
207	
208	const policyAdjustment = (
209	  policyBase: number,
210	  customer: Customer,
211	  precedingSteps: number,
212	): number =>
213	  percentOf(policyBase, netPolicyAdjustmentPercent(customer, precedingSteps));
214	
215	const quotePremium = (
216	  items: Item[],
217	  customer: Customer,
218	  precedingSteps: number,
219	): number => {
220	  const basePremium = policyBasePremium(items);
221	  return roundPremiumUp(
222	    basePremium +
223	      totalItemSurcharges(items) +
224	      policyAdjustment(basePremium, customer, precedingSteps) +
225	      PROCESSING_FEE,
226	  );
227	};
228	
229	const roundPayoutDown = (payout: number): number => Math.floor(payout);
230	
231	/**
232	 * Goes through `priceOf` for the same reason the premium side does: an unknown
233	 * type would otherwise index to `undefined` and sum to a NaN cap, which
234	 * `Math.min` would carry into a NaN payout instead of an error. This is a
235	 * guarded lookup, not a derivation — the two price lists stay independent.
236	 */
237	const insuranceSum = (items: Item[]): number =>
238	  items.reduce(
239	    (sum, item) => sum + priceOf(INSURANCE_VALUE_BY_ITEM_TYPE, item.type),
240	    0,
241	  );
242	
243	/**
244	 * The MHPCO settles damage only to what it insures. Throwing here rather than
245	 * returning undefined means an uninsured item cannot be quietly paid out.
246	 *
247	 * ONE check covers both halves of the spec's error bullet, and two tests now
248	 * hold it there: "rejects a claim whose damage references an item not covered
249	 * by the policy" (amulet damage against a sword-only policy) and "rejects a
250	 * claim whose damage references an unknown item type" (broomstick). The second
251	 * needed no code — an unknown type is a strict subset of "not among the
252	 * policy's items", since nothing unknown can be on a policy in the first place;
253	 * a quote naming one is rejected by `priceOf` before any claim can reference it.
254	 *
255	 * Do NOT route this through `priceOf` to unify the two "unknown item" errors.
256	 * The domains differ: an amulet is a perfectly KNOWN type, so `priceOf` would
257	 * return 600 and the uninsured-amulet claim would silently pay out. Membership
258	 * in this policy, not membership on the price list, is the question here.
259	 */
260	const damagedItem = (damage: Damage, policyItems: Item[]): Item => {
261	  const item = policyItems.find((it) => it.type === damage.itemType);
262	  if (item === undefined) {
263	    throw new Error(`item not covered by the policy: ${damage.itemType}`);
264	  }
265	  return item;
266	};
267	
268	/**
269	 * What the MHPCO reimburses for ONE damaged item, before the deductible.
270	 * Highly enchanted items are reimbursed at half the damage amount.
271	 *
272	 * NOT A BUG: the spec's "dragon material is fully reimbursed" clause is
273	 * deliberately absent, because no example can observe it. Full reimbursement is
274	 * already what happens when no clause fires, so below enchantment 8 a dragon
275	 * item is indistinguishable from a steel one; at enchantment >= 8 the spec says
276	 * the 50 % rule wins, so dragon is indistinguishable again. The clause has no
277	 * input that would change an output — adding it would be unfalsifiable by the
278	 * suite. Both dragon tests below pass against this code for exactly the reasons
279	 * their comments state. If a future rule ever makes material observable (say, a
280	 * dragon-only exemption from the deductible, or a clause the 50 % rule does not
281	 * override), add it then, driven by that example.
282	 *
283	 * The enchantment is read from the FIRST policy item of the damaged type — see
284	 * `damagedItem`, which throws if the policy covers no such type at all. Since
285	 * `rejectSurplusDamages` now bounds the damages of a type by the number
286	 * insured, the remaining gap is narrow: a policy holding alike items that
287	 * DIFFER in enchantment, damaged within that count, reimburses every one of
288	 * them at the first item's enchantment. Two enchantment-9 swords are settled
289	 * correctly; an enchantment-9 and an enchantment-3 sword are not. Pairing each
290	 * damage with a distinct item needs an example that says which one a claim
291	 * refers to, and the spec's damages name only a type.
292	 */
293	const reimbursementFor = (damage: Damage, policyItems: Item[]): number =>
294	  enchantmentAtLeast(
295	    damagedItem(damage, policyItems),
296	    HIGH_ENCHANTMENT_PAYOUT_THRESHOLD,
297	  )
298	    ? percentOf(damage.amount, HIGH_ENCHANTMENT_PAYOUT_PERCENT)
299	    : damage.amount;
300	
301	/**
302	 * One damaged item's contribution to the payout. The deductible comes off ONCE
303	 * PER DAMAGED ITEM, not once per incident — expressing it at the level of a
304	 * single damage is what makes that per-item scope structural rather than a
305	 * remark about where a subtraction happens to sit.
306	 */
307	const payoutForDamage = (damage: Damage, policyItems: Item[]): number =>
308	  reimbursementFor(damage, policyItems) - DEDUCTIBLE;
309	
310	/**
311	 * The MHPCO will not pay twice for one insured item. Two sword damages against
312	 * a single insured sword is a malformed claim, not a double loss — and the
313	 * spec rejects the WHOLE claim rather than dropping the surplus entry, so this
314	 * is checked up front for the entire incident before anything is paid.
315	 */
316	const rejectSurplusDamages = (
317	  incident: Incident,
318	  policyItems: Item[],
319	): void => {
320	  const covered = countAlikeItems(policyItems);
321	  const claimed = countByKey(incident.damages, (damage) => damage.itemType);
322	
323	  for (const [itemType, count] of claimed) {
324	    if (count > (covered.get(itemType) ?? 0)) {
325	      throw new Error(`more ${itemType} damages than the policy covers`);
326	    }
327	  }
328	};
329	
330	/**
331	 * A negative loss is not a loss. Left unchecked such an entry would not merely
332	 * misprice the claim: it subtracts from the payout and so ADDS to the policy's
333	 * remaining cap, letting a claimant raise their own ceiling.
334	 */
335	const rejectNegativeDamages = (incident: Incident): void => {
336	  for (const damage of incident.damages) {
337	    if (damage.amount < 0) {
338	      throw new Error(`damage amount cannot be negative: ${damage.amount}`);
339	    }
340	  }
341	};
342	
343	/**
344	 * Every way a claim can be malformed, checked before a single G is settled.
345	 * The spec rejects the WHOLE claim in each case rather than dropping the
346	 * offending entry, so all of these run up front for the entire incident.
347	 *
348	 * The rules stay separate functions because each throws for a distinct reason
349	 * with a distinct message. They are called directly rather than through a
350	 * uniform list: only one of them needs the policy items, and a shared
351	 * signature would buy dispatch uniformity at the price of an unused parameter.
352	 */
353	const rejectMalformedClaim = (
354	  incident: Incident,
355	  policyItems: Item[],
356	): void => {
357	  rejectNegativeDamages(incident);
358	  rejectSurplusDamages(incident, policyItems);
359	};
360	
361	/**
362	 * The whole incident's payout, before rounding — the per-item payouts summed,
363	 * and nothing else: validation is the caller's business, so this function does
364	 * only what its name says. NOT named for reimbursement: `reimbursementFor` is
365	 * the amount BEFORE the deductible, and reusing that word here would invite a
366	 * reader to subtract it a second time.
367	 */
368	const payoutBeforeRounding = (
369	  incident: Incident,
370	  policyItems: Item[],
371	): number =>
372	  incident.damages.reduce(
373	    (total, damage) => total + payoutForDamage(damage, policyItems),
374	    0,
375	  );
376	
377	/**
378	 * Anything that is not a claim is treated as a quote, which is why this names
379	 * the claim case rather than offering an `isQuote` counterpart: a two-sided
380	 * pair would imply a third possibility the code does not handle. See the Step
381	 * doc comment on why `op` is a plain string.
382	 */
383	const isClaim = (step: Step): boolean => step.op === "claim";
384	
385	/** A claim's `policy` field is the index of the quote step that wrote it. */
386	const itemsCoveredBy = (policy: number, scenario: Scenario): Item[] =>
387	  scenario.steps[policy].items ?? [];
388	
389	/** The MHPCO caps a policy at twice its insurance sum. */
390	const capFor = (policyItems: Item[]): number =>
391	  CAP_MULTIPLE * insuranceSum(policyItems);
392	
393	/**
394	 * A policy's cap is consumed cumulatively: each payout draws down what remains,
395	 * and a claim can never pay out more than is left. The clamp is applied AFTER
396	 * rounding, so a fractional payout cannot round its way past the remaining cap.
397	 *
398	 * A malformed claim is rejected here, before any of that: this is the first
399	 * point at which both the incident and the items it is claimed against are in
400	 * hand, and rejecting up front means no ledger state is touched on the way to
401	 * a throw.
402	 *
403	 * Takes the policy's items and its remaining cap rather than looking either up,
404	 * which keeps the arithmetic of a single claim free of the ledger's bookkeeping.
405	 * `capLedger.settle` resolves both and is the only caller.
406	 */
407	const settleClaim = (
408	  incident: Incident,
409	  policyItems: Item[],
410	  remainingBefore: number,
411	): ClaimResult => {
412	  rejectMalformedClaim(incident, policyItems);
413	  const desired = roundPayoutDown(payoutBeforeRounding(incident, policyItems));
414	  const payout = Math.min(desired, remainingBefore);
415	  return { payout, remainingCap: remainingBefore - payout };
416	};
417	
418	/**
419	 * Tracks what each policy has left of its cap as claims land against it, and
420	 * settles claims against it. A policy is seeded from its items the first time
421	 * it is claimed against, which is why this needs the scenario: the cap is a
422	 * property of the covered items, and those live in the quote step the claim
423	 * points at.
424	 *
425	 * Settling lives here rather than in the caller because the drawdown is the
426	 * whole reason the ledger exists: reading what remains, paying out of it, and
427	 * writing back what is left are one indivisible step, and a caller that could
428	 * read without writing back could silently let a policy pay twice over.
429	 */
430	const capLedger = (scenario: Scenario) => {
431	  const remainingByPolicy = new Map<number, number>();
432	
433	  return {
434	    settle: (policy: number, incident: Incident): ClaimResult => {
435	      const policyItems = itemsCoveredBy(policy, scenario);
436	      const remainingBefore =
437	        remainingByPolicy.get(policy) ?? capFor(policyItems);
438	      const result = settleClaim(incident, policyItems, remainingBefore);
439	      remainingByPolicy.set(policy, result.remainingCap);
440	      return result;
441	    },
442	  };
443	};
444	
445	/**
446	 * Steps are processed in order because claims draw down a policy's remaining
447	 * cap, so each result depends on the claims before it.
448	 */
449	export const runScenario = (scenario: Scenario): ScenarioResult => {
450	  const caps = capLedger(scenario);
451	
452	  const results = scenario.steps.map((step, precedingSteps) => {
453	    if (isClaim(step)) {
454	      // Non-null: only claim steps reach here, and every claim carries an
455	      // incident. See the Step doc comment.
456	      return caps.settle(step.policy ?? 0, step.incident!);
457	    }
458	
459	    return {
460	      premium: quotePremium(step.items ?? [], scenario.customer, precedingSteps),
461	    };
462	  });
463	
464	  return { results };
465	};
466

1	import { readFileSync } from "node:fs";
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	/**
5	 * File descriptor 0 is stdin. Reading it synchronously rather than streaming is
6	 * deliberate: a scenario is a single JSON document that must be complete before
7	 * it can be parsed at all, so there is nothing to do with a partial read.
8	 */
9	const STDIN_FD = 0;
10	
11	/**
12	 * The cast is unchecked — `JSON.parse` returns `any`, and nothing here verifies
13	 * the document is a well-formed Scenario. That is not an oversight: the engine
14	 * already rejects the malformed cases the spec names (unknown item types,
15	 * uninsured damages, negative amounts) with domain-specific messages, and the
16	 * upcoming CLI error test drives turning those throws into a non-zero exit.
17	 * A schema check here would duplicate those rules in a second, weaker form.
18	 */
19	const readScenarioFromStdin = (): Scenario =>
20	  JSON.parse(readFileSync(STDIN_FD, "utf8")) as Scenario;
21	
22	/**
23	 * A rejected scenario is a report about the input, not a program failure, so
24	 * the operator gets the description alone — a stack trace would bury it. The
25	 * result is written only after the run succeeds, so a rejected scenario leaves
26	 * stdout empty rather than emitting partial results.
27	 */
28	try {
29	  const results = runScenario(readScenarioFromStdin());
30	  process.stdout.write(JSON.stringify(results));
31	} catch (rejection) {
32	  process.stderr.write(`${(rejection as Error).message}\n`);
33	  process.exit(1);
34	}
